import React, { useState, useEffect, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import { API_URL } from '../config';

const Dashboard = () => {
  const { token, loading, user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [enrollments, setEnrollments] = useState([]);
  const [loadingEnrollments, setLoadingEnrollments] = useState(true);

  useEffect(() => {
    if (!loading && !token) navigate('/login');
  }, [token, loading]);

  useEffect(() => {
    if (!token) return;
    fetch(`${API_URL}/auth/me/enrollments`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.ok ? res.json() : [])
      .then(setEnrollments)
      .finally(() => setLoadingEnrollments(false));
  }, [token]);

  if (loading || !token) {
    return <div className="min-h-screen flex items-center justify-center text-slate-500 text-sm">Chargement...</div>;
  }

  return (
    <div className="min-h-screen text-white">
      <Navbar />
      <div className="max-w-4xl mx-auto px-6 py-16">
        <h1 className="text-2xl font-bold mb-1">Mon apprentissage</h1>
        <p className="text-slate-500 text-sm mb-10">Content de te revoir{user?.email ? `, ${user.email.split('@')[0]}` : ''}.</p>

        {loadingEnrollments ? (
          <p className="text-slate-500 text-sm">Chargement de tes formations...</p>
        ) : enrollments.length > 0 ? (
          <div className="space-y-4">
            {enrollments.map(e => {
              const percent = e.total_lessons > 0 ? Math.round((e.completed_lessons / e.total_lessons) * 100) : 0;
              return (
                <div key={e.course_id} className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 hover:border-blue-500/40 transition-colors duration-300">
                  <div className="flex items-center justify-between mb-4">
                    <div>
                      <span className="text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full bg-blue-500/10 text-blue-400">
                        {e.payment_method ? e.payment_method.toUpperCase() : 'Gratuit'}
                      </span>
                      <h3 className="text-lg font-bold mt-3">{e.course_title}</h3>
                    </div>
                    <Link to={`/player/${e.course_id}`} className="bg-blue-600 hover:bg-blue-500 text-white font-semibold text-sm px-5 py-2.5 rounded-lg transition-colors shrink-0">
                      Continuer
                    </Link>
                  </div>
                  <div className="w-full bg-slate-800 h-2 rounded-full overflow-hidden">
                    <div className="h-full bg-gradient-to-r from-blue-600 to-cyan-500 rounded-full transition-all duration-500" style={{ width: `${percent}%` }}></div>
                  </div>
                  <p className="text-xs text-slate-500 mt-2">{e.completed_lessons} / {e.total_lessons} leçons — {percent}% complété</p>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="border border-dashed border-slate-800 rounded-2xl p-12 text-center">
            <p className="text-slate-500 text-sm mb-4">Tu n'as encore commencé aucune formation.</p>
            <Link to="/catalog" className="text-blue-400 hover:text-blue-300 font-semibold text-sm">Découvrir le catalogue →</Link>
          </div>
        )}
      </div>
    </div>
  );
};
export default Dashboard;
